void mainImage(out vec4 couleurSortie, vec2 coordonneesPixel) {
    vec2 st = (coordonneesPixel - .5 * iResolution.xy) / iResolution.y;

    float angleCamera = iTime * .08;
    mat2 rotationCamera = mat2(cos(angleCamera), -sin(angleCamera), sin(angleCamera), cos(angleCamera));

    vec3 rayon = normalize(vec3(st, 1.2));
    vec3 positionCamera = vec3(0., 2.5, -5.);

    rayon.yz *= mat2(.85, -.52, .52, .85);
    rayon.xz *= rotationCamera;
    positionCamera.xz *= rotationCamera;

    float distanceParcourue = 0.;
    vec3 positionHit = vec3(0.);
    bool hit = false;

    for(int i = 0; i < 80; i++) {
        vec3 p = positionCamera + rayon * distanceParcourue;

        vec3 posGerstner = vec3(p.x, 0., p.z);
        float amplitude = .35;
        float frequence = .6;
        float nombreOnde = .8;
        float raideur = .8;
        vec2 dir = normalize(vec2(1., .4));

        for(int j = 0; j < 6; j++) {
            float phase = nombreOnde * dot(dir, p.xz) + frequence * iTime;
            posGerstner.xz -= dir * (raideur / nombreOnde) * amplitude * cos(phase);
            posGerstner.y  += amplitude * sin(phase);

            dir *= mat2(.6, .8, -.8, .6);
            amplitude *= .48;
            frequence *= 1.35;
            nombreOnde *= 1.5;
        }

        float hauteurDiff = p.y - posGerstner.y;

        if(abs(hauteurDiff) < .001) {
            positionHit = p;
            hit = true;
            break;
        }

        distanceParcourue += hauteurDiff * .3;
        if(distanceParcourue > 40.) break;
    }

    if(hit) {
        vec2 pXZ = positionHit.xz;

        vec3 normalLocal = vec3(0., 1., 0.);
        float amplitude = .35;
        float frequence = .6;
        float nombreOnde = .8;
        float raideur = .8;
        vec2 dir = normalize(vec2(1., .4));

        for(int j = 0; j < 6; j++) {
            float phase = nombreOnde * dot(dir, pXZ) + frequence * iTime;
            float c = cos(phase);
            float s = sin(phase);

            float WA = nombreOnde * amplitude;

            normalLocal.x -= dir.x * WA * c;
            normalLocal.z -= dir.y * WA * c;
            normalLocal.y -= raideur * WA * s;

            dir *= mat2(.6, .8, -.8, .6);
            amplitude *= .48;
            frequence *= 1.35;
            nombreOnde *= 1.5;
        }

        vec3 normale = normalize(normalLocal);

        vec3 lumiereDirection = normalize(vec3(-.5, .4, -.6));
        vec3 vueDirection = -rayon;

        float cosTheta = max(dot(normale, vueDirection), 0.);
        float fresnel = .02 + .98 * pow(1. - cosTheta, 5.);

        vec3 demiVecteur = normalize(lumiereDirection + vueDirection);
        float spec = pow(max(dot(normale, demiVecteur), 0.), 256.);

        vec3 couleurProfonde = vec3(.005, .08, .15);
        vec3 couleurSurface = vec3(.02, .25, .35);
        vec3 couleurSoleil = vec3(1.0, .95, .8);
        vec3 couleurCielBas = vec3(.5, .7, .85);

        vec3 couleureDiffuse = mix(couleurProfonde, couleurSurface, max(positionHit.y * 1.5 + .5, 0.));

        vec3 couleurReflet = mix(couleurCielBas, couleurSoleil, pow(max(dot(reflect(-vueDirection, normale), lumiereDirection), 0.), 8.));

        vec3 couleurFinale = mix(couleureDiffuse, couleurReflet, fresnel);
        couleurFinale += couleurSoleil * spec * 2.5;

        float brouillard = 1. - exp(-distanceParcourue * .025);
        couleurFinale = mix(couleurFinale, couleurCielBas, brouillard);

        couleurSortie = vec4(pow(couleurFinale, vec3(1. / 2.2)), 1.);
    } else {
        vec3 couleurCiel = mix(vec3(.5, .7, .85), vec3(.15, .35, .65), max(rayon.y, 0.));
        couleurSortie = vec4(pow(couleurCiel, vec3(1. / 2.2)), 1.);
    }
}
